import random


def generate(seed: int = 0) -> list[str]:
    """Level-order inputs build valid binary trees; node values and node counts stay in bounds."""
    r = random.Random(seed)
    cases = [[], [1], [3, 9, 20, None, None, 15, 7]]
    seen = {tuple(x) for x in cases}
    while len(cases) < 600:
        n = r.randint(1, 100)
        a = [r.randint(-100, 100) for _ in range(n)]
        key = tuple(a)
        if key not in seen:
            seen.add(key)
            cases.append(a)
    return [f"candidate(root=tree_node({a!r}))" for a in cases]


